input.script:
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
all = fold acc = first.items for page in remaining { return acc + page }
companies = list_companies({})
dmap = fold acc = {} for co in companies {
    return acc + ({ [co.domain]: co.name } if co.domain != null and co.name != null else {})
}
processed = for c in all {
    phone = c.phone if c.phone != null else ""
    digits = regex.replace(phone, "[^0-9]", "")
    candidate = if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else {
        return null
    }
    new_phone = if candidate != null and candidate != phone { return candidate } else { return null }
    email = c.email if c.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) > 1 else ""
    needs = c.company == null or c.company == ""
    new_company = if needs and domain != "" and domain in dmap { return dmap[domain] } else { return null }
    u = update_contact({ id: c.id, phone: new_phone, company: new_company }) if new_phone != null or new_company != null
    return { pf: 1 if new_phone != null else 0, cf: 1 if new_company != null else 0 }
}
phones_fixed = fold acc = 0 for p in processed { return acc + p.pf }
companies_filled = fold acc = 0 for p in processed { return acc + p.cf }
result = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return result
